"use strict";
const APP={name:"REMESAS",version:"4.3.2",lang:localStorage.getItem("remesas_lang_v4")||"es",session:null,config:null,access:null,moneyKey:"remesas_money_v4",expensesKey:"remesas_expenses_v4",familyKey:"remesas_family_v4",prefsKey:"remesas_prefs_v4",savingsKey:"remesas_savings_v4",plansKey:"remesas_plans_v4"};
const app=document.getElementById("app");
const esc=v=>String(v??"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#039;");
const t=(es,en)=>APP.lang==="en"?en:es;
const money=v=>new Intl.NumberFormat(APP.lang==="en"?"en-US":"es-US",{style:"currency",currency:"USD",maximumFractionDigits:2}).format(Number(v||0));
const num=v=>Number(v||0);
function getJSON(k,f){try{return JSON.parse(localStorage.getItem(k)||"")??f}catch{return f}}
function setJSON(k,v){localStorage.setItem(k,JSON.stringify(v))}
function token(){return APP.access||localStorage.getItem("remesas_access_v4")||""}
function headers(extra={}){const h={"Content-Type":"application/json",...extra},x=token();if(x)h["X-Remesas-Access-Token"]=x;h["X-Remesas-Language"]=APP.lang;return h}
async function api(url,options={}){const r=await fetch(url,{...options,headers:headers(options.headers||{})});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.detail||d.error||d.message||t("No se pudo completar esta acción.","This action could not be completed."));return d}
async function loadConfig(){try{APP.config=await api(`/api/config?language=${encodeURIComponent(APP.lang)}`)}catch{APP.config=APP.config||{app:{brand:"May Roga LLC"},countries:[],delivery_methods:[],payment_methods:[],help_topics:[]}}return APP.config}
async function serviceStatus(){try{return await api("/api/access/status")}catch{return{active:false,remaining_seconds:0}}}
async function startService(){try{const d=await api("/api/service/start",{method:"POST",body:"{}"});APP.session=d.session;return true}catch(e){showError(e.message);return false}}
async function verifyAccess(){const s=await serviceStatus();if(s.active){APP.access=token();return true}return false}
function topbar(title="REMESAS"){return`<header class="topbar"><button class="btn secondary small" onclick="renderHome()" aria-label="${esc(t("Inicio","Home"))}">⌂</button><strong class="brand">${esc(title)}</strong><div class="top-actions"><button class="btn lang-btn small" onclick="changeLanguage()">${APP.lang==="es"?"EN":"ES"}</button></div></header>`}
function renderShell(content,title="REMESAS"){app.innerHTML=`<div class="app-shell">${topbar(title)}<main>${content}</main></div>`;scrollTo(0,0)}
function card(title,text,action,icon=""){return`<button class="action-card" onclick="${action}"><span class="action-icon">${icon}</span><strong>${esc(title)}</strong><small>${esc(text)}</small></button>`}
function homeStats(){const m=getMoneyState(),e=getExpenses(),f=getFamily(),s=getSavings(),p=getPlans();return`<div class="balance-grid"><div class="balance"><small>${esc(t("Disponible","Available"))}</small><b>${money(m.available)}</b><span>${esc(t("Lo que queda después de lo que registraste.","What remains after what you recorded."))}</span></div><div class="balance"><small>${esc(t("Gastos","Expenses"))}</small><b>${e.length}</b><span>${esc(t("Pagos que has anotado.","Payments you recorded."))}</span></div><div class="balance"><small>${esc(t("Familia","Family"))}</small><b>${f.length}</b><span>${esc(t("Personas que quieres recordar.","People you want to remember."))}</span></div><div class="balance"><small>${esc(t("Ahorros","Savings"))}</small><b>${s.length}</b><span>${esc(t("Dinero que decidiste guardar.","Money you chose to set aside."))}</span></div><div class="balance"><small>${esc(t("Planes","Plans"))}</small><b>${p.length}</b><span>${esc(t("Cosas que quieres lograr.","Things you want to achieve."))}</span></div></div>`}
function renderHome(){const o=APP.config?.opening||{},brand=APP.config?.app?.brand||"May Roga LLC";app.innerHTML=`<div class="app-shell"><header class="hero"><div class="topbar"><strong class="brand">REMESAS<br><small>${esc(brand)}</small></strong><div class="top-actions"><button class="btn lang-btn small" onclick="changeLanguage()">${APP.lang==="es"?"EN":"ES"}</button></div></div><h1>${esc(t("TU DINERO, MÁS CLARO","YOUR MONEY, CLEARER"))}</h1><p>${esc(t("Entiende tu dinero con palabras sencillas. Mira qué tienes, qué entra, qué sale y qué puedes hacer.","Understand your money in simple words. See what you have, what comes in, what goes out, and what you can do."))}</p><div class="hero-actions"><button class="btn" onclick="renderRemittance()">💸 ${esc(t("QUIERO ENVIAR DINERO","I WANT TO SEND MONEY"))}</button><button class="btn secondary" onclick="renderHelp()">❓ ${esc(t("NO SÉ QUÉ HACER","I DON'T KNOW WHAT TO DO"))}</button></div></header><main><section class="section"><div class="section-title"><div><h2>${esc(t("Tu dinero, paso a paso","Your money, step by step"))}</h2><p>${esc(t("Cada número tiene una explicación. Nada aparece solo.","Every number has an explanation. Nothing appears alone."))}</p></div></div><div class="grid three">${card("TENGO","Lo que tienes ahora.","renderTengo()","💵")}${card("GANO","Lo que entra y de dónde viene.","renderGano()","➕")}${card("GASTO","Lo que sale y en qué se va.","renderExpenses()","➖")}${card("AHORRO","Lo que decides guardar.","renderSavings()","🏦")}${card("QUIERO","Lo que quieres comprar, lograr o ayudar.","renderGoals()","🛒")}${card("PUEDO","Lo que queda después de tus decisiones.","renderPuedo()","📅")}${card("HAGO","La siguiente acción clara.","renderHago()","✅")}</div>${homeStats()}</section><section class="section"><div class="grid two">${card("GUÍA RÁPIDA","Te lleva paso a paso para preparar una remesa.","renderQuickGuide()","🧭")}${card("APRENDER","Aprende sin palabras complicadas.","renderLearn()","📖")}${card("COMPARAR","Mira las cuatro remesadoras en un solo lugar.","renderRemittance()","🔎")}${card("PDF DE MI DINERO","Guarda una copia de lo que organizaste.","exportMoneyPDF()","📄")}${card("ENTRAR PDF","Trae un PDF de REMESAS y recupera tus datos.","pickPDF()","📥")}${card("AYUDA","Pregunta y recibe una respuesta corta.","renderHelp()","❓")}</div></section><section class="section"><div class="card"><h2>${esc(t("¿Qué quieres resolver hoy?","What do you want to solve today?"))}</h2><p>${esc(t("Escríbelo como se lo dirías a una persona.","Write it the way you would tell a person."))}</p><textarea id="freeNeed" maxlength="2000" placeholder="${esc(t("Ejemplo: quiero mandar $200 a México y quiero saber si me alcanza.","Example: I want to send $200 to Mexico and know if I can afford it."))}"></textarea><button class="btn" onclick="understandNeed()">${esc(t("AYÚDAME CON ESTO","HELP ME WITH THIS"))}</button></div></section><section class="section"><div class="legal"><b>${esc(t("Para tu tranquilidad","For your peace of mind"))}</b><p>${esc(t("REMESAS te ayuda a entender y organizar tus propios datos. No recibe ni envía tu dinero. Antes de enviar, revisa la cantidad, el destinatario y las condiciones que muestre la remesadora oficial.","REMESAS helps you understand and organize your own information. It does not receive or send your money. Before sending, review the amount, recipient, and conditions shown by the official provider."))}</p></div><button class="btn danger" onclick="deleteLocalData()">${esc(t("BORRAR MIS DATOS","DELETE MY DATA"))}</button></section><footer class="footer">${esc(brand)} · REMESAS ${esc(APP.version)}<div class="footer-links"><button onclick="renderHelp()">${esc(t("Ayuda","Help"))}</button><button onclick="renderAbout()">${esc(t("Privacidad","Privacy"))}</button></div></footer></main></div>`}
function renderTengo(){const m=getMoneyState();renderShell(`<section class="section"><div class="card"><h1>💵 ${esc(t("TENGO","I HAVE"))}</h1><p>${esc(t("Primero sabemos con cuánto cuentas. Así no hacemos planes con dinero que no tienes.","First we find out what you have. That way we do not plan with money you do not have."))}</p><label>${esc(t("¿Cuánto dinero tienes disponible ahora?","How much money do you have available now?"))}</label><input id="haveAmount" type="number" min="0" step=".01" value="${esc(m.have||"")}"><button class="btn" onclick="saveTengo()">${esc(t("GUARDAR Y VER QUÉ SIGNIFICA","SAVE AND SEE WHAT IT MEANS"))}</button><div id="tengoResult"></div></div></section>`,t("TENGO","I HAVE"));if(m.have!=null)showTengo(m.have)}
function saveTengo(){const v=num(document.getElementById("haveAmount")?.value);if(v<0){showError(t("Escribe una cantidad válida.","Enter a valid amount."));return}const m=getMoneyState();m.have=v;m.available=v+num(m.incomeTotal)-num(m.expenseTotal)-num(m.savingsTotal)-num(m.remittance);m.updatedAt=new Date().toISOString();setJSON(APP.moneyKey,m);showTengo(v)}
function showTengo(v){const b=document.getElementById("tengoResult");if(!b)return;b.innerHTML=`<div class="notice"><h3>${money(v)}</h3><p>${esc(t(`Ese número es el dinero que dices que tienes disponible ahora. Lo usamos como punto de partida. Cuando registres gastos, ahorro o una remesa, el dinero disponible cambiará porque ese dinero ya tendrá un destino.`,`That number is the money you say you have available now. We use it as the starting point. When you record expenses, savings, or a remittance, available money changes because that money now has a purpose.`))}</p></div><button class="btn secondary" onclick="renderPuedo()">${esc(t("¿QUÉ PUEDO HACER CON ESTO?","WHAT CAN I DO WITH THIS?"))}</button>`}
function renderGano(){const m=getMoneyState();renderShell(`<section class="section"><div class="card"><h1>➕ ${esc(t("GANO","I EARN"))}</h1><p>${esc(t("Aquí anotamos el dinero que entra. Saber cuánto entra ayuda a saber cuánto puedes gastar, guardar o enviar.","Here we record money coming in. Knowing what comes in helps you know what you can spend, save, or send."))}</p><label>${esc(t("¿Cuánto recibes?","How much do you receive?"))}</label><input id="gainAmount" type="number" min="0" step=".01" value="${esc(m.income||"")}"><label>${esc(t("¿Cada cuánto?","How often?"))}</label><select id="gainFreq"><option value="weekly">${esc(t("Cada semana","Every week"))}</option><option value="biweekly">${esc(t("Cada quincena","Every two weeks"))}</option><option value="monthly">${esc(t("Cada mes","Every month"))}</option></select><label>${esc(t("¿De dónde viene?","Where does it come from?"))}</label><input id="gainSource" maxlength="100" value="${esc(m.incomeSource||"")}" placeholder="${esc(t("Trabajo, negocio, ayuda...","Work, business, help..."))}"><button class="btn" onclick="saveGano()">${esc(t("GUARDAR Y EXPLICAR","SAVE AND EXPLAIN"))}</button><div id="ganoResult"></div></div></section>`,t("GANO","I EARN"));document.getElementById("gainFreq").value=m.incomeFreq||"monthly"}
function freqFactor(f){return f==="weekly"?52/12:f==="biweekly"?26/12:1}
function saveGano(){const v=num(document.getElementById("gainAmount")?.value),f=document.getElementById("gainFreq")?.value||"monthly",src=(document.getElementById("gainSource")?.value||"").trim();if(v<0){showError(t("Escribe una cantidad válida.","Enter a valid amount."));return}const m=getMoneyState();m.income=v;m.incomeFreq=f;m.incomeSource=src;m.monthlyIncome=v*freqFactor(f);m.incomeTotal=m.monthlyIncome;recalcMoney(m);setJSON(APP.moneyKey,m);const b=document.getElementById("ganoResult");b.innerHTML=`<div class="notice"><h3>${money(m.monthlyIncome)}</h3><p>${esc(t(`Este es el equivalente mensual de lo que recibes. Lo usamos para comparar tus entradas con tus gastos. Si cobras cada semana o quincena, lo pasamos a una misma medida para poder verlo con claridad.`,`This is the monthly equivalent of what you receive. We use it to compare your income with your expenses. If you are paid weekly or every two weeks, we convert it to one measure so it is easier to see.`))}</p>${src?`<p>${esc(t(`Lo registraste como: ${src}.`,`You recorded it as: ${src}.`))}</p>`:""}</div><button class="btn secondary" onclick="renderPuedo()">${esc(t("VER QUÉ ME QUEDA","SEE WHAT I HAVE LEFT"))}</button>`}
function getMoneyState(){return getJSON(APP.moneyKey,{have:0,income:0,incomeFreq:"monthly",incomeSource:"",monthlyIncome:0,incomeTotal:0,expenseTotal:0,savingsTotal:0,remittance:0,available:0,updatedAt:null})}
function recalcMoney(m){const e=getExpenses(),s=getSavings(),r=num(m.remittance||0);m.expenseTotal=e.reduce((a,x)=>a+num(x.monthlyAmount??x.amount),0);m.savingsTotal=s.reduce((a,x)=>a+num(x.amount),0);const base=num(m.have||0)+num(m.incomeTotal||m.monthlyIncome||0);m.available=base-num(m.expenseTotal)-num(m.savingsTotal)-r;return m}
function renderExpenses(){const e=getExpenses();renderShell(`<section class="section"><div class="card"><h1>➖ ${esc(t("GASTO","SPEND"))}</h1><p>${esc(t("Cada gasto que anotas explica por qué baja tu dinero disponible.","Every expense you record explains why your available money goes down."))}</p><label>${esc(t("¿En qué gastaste?","What did you spend on?"))}</label><input id="expenseName" maxlength="120" placeholder="${esc(t("Comida, casa, carro...","Food, home, car..."))}"><label>${esc(t("¿Cuánto?","How much?"))}</label><input id="expenseAmount" type="number" min=".01" step=".01"><label>${esc(t("¿Cada cuánto?","How often?"))}</label><select id="expenseFrequency"><option value="monthly">${esc(t("Cada mes","Every month"))}</option><option value="weekly">${esc(t("Cada semana","Every week"))}</option><option value="biweekly">${esc(t("Cada quincena","Every two weeks"))}</option><option value="one_time">${esc(t("Una sola vez","One time"))}</option></select><button class="btn" onclick="addExpense()">${esc(t("GUARDAR GASTO","SAVE EXPENSE"))}</button></div><div class="list">${e.length?e.map((x,i)=>`<div class="card"><b>${esc(x.description)}</b><strong>${money(x.amount)}</strong><p class="small">${esc(freqText(x.frequency))}${x.frequency!=="one_time"?` · ${money(x.monthlyAmount)}/${t("mes","month")}`:""}</p><button class="btn danger small" onclick="removeExpense(${i})">${esc(t("Borrar","Delete"))}</button></div>`).join(""):`<div class="empty">${esc(t("Todavía no has anotado gastos.","You have not recorded expenses yet."))}</div>`}</div><button class="btn secondary" onclick="renderPuedo()">${esc(t("VER QUÉ CAMBIÓ","SEE WHAT CHANGED"))}</button></section>`,t("GASTO","SPEND"))}
function freqText(f){return f==="weekly"?t("Cada semana","Every week"):f==="biweekly"?t("Cada quincena","Every two weeks"):f==="monthly"?t("Cada mes","Every month"):t("Una sola vez","One time")}
function getExpenses(){return getJSON(APP.expensesKey,[])}
function addExpense(){const d=(document.getElementById("expenseName")?.value||"").trim(),a=num(document.getElementById("expenseAmount")?.value),f=document.getElementById("expenseFrequency")?.value||"monthly";if(!d||a<=0){showError(t("Escribe qué fue y cuánto costó.","Enter what it was and how much it cost."));return}const e=getExpenses(),monthlyAmount=f==="weekly"?a*52/12:f==="biweekly"?a*26/12:f==="one_time"?a:a;e.push({description:d,amount:a,frequency:f,monthlyAmount,createdAt:new Date().toISOString()});setJSON(APP.expensesKey,e);const m=getMoneyState();recalcMoney(m);setJSON(APP.moneyKey,m);renderExpenses()}
function removeExpense(i){const e=getExpenses();e.splice(i,1);setJSON(APP.expensesKey,e);const m=getMoneyState();recalcMoney(m);setJSON(APP.moneyKey,m);renderExpenses()}
function getSavings(){return getJSON(APP.savingsKey,[])}
function renderSavings(){const s=getSavings();renderShell(`<section class="section"><div class="card"><h1>🏦 ${esc(t("AHORRO","SAVINGS"))}</h1><p>${esc(t("Ahorrar no significa perder ese dinero. Significa ponerlo aparte para algo que te importa.","Saving does not mean losing that money. It means setting it aside for something that matters to you."))}</p><label>${esc(t("¿Cuánto quieres guardar?","How much do you want to save?"))}</label><input id="saveAmount" type="number" min=".01" step=".01"><label>${esc(t("¿Para qué?","What for?"))}</label><input id="savePurpose" maxlength="100" placeholder="${esc(t("Casa, carro, viaje, emergencia...","Home, car, trip, emergency..."))}"><button class="btn" onclick="saveSavings()">${esc(t("GUARDAR Y VER QUÉ CAMBIA","SAVE AND SEE WHAT CHANGES"))}</button></div><div class="list">${s.length?s.map((x,i)=>`<div class="card"><b>${esc(x.purpose||t("Ahorro","Savings"))}</b><strong>${money(x.amount)}</strong><p>${esc(t("Este dinero está apartado para ese propósito.","This money is set aside for that purpose."))}</p><button class="btn danger small" onclick="removeSavings(${i})">${esc(t("Borrar","Delete"))}</button></div>`).join(""):`<div class="empty">${esc(t("Todavía no has separado dinero para una meta.","You have not set money aside for a goal yet."))}</div>`}</div></section>`,t("AHORRO","SAVINGS"))}
function saveSavings(){const a=num(document.getElementById("saveAmount")?.value),p=(document.getElementById("savePurpose")?.value||"").trim();if(a<=0||!p){showError(t("Dime cuánto quieres guardar y para qué.","Tell me how much you want to save and what it is for."));return}const s=getSavings();s.push({amount:a,purpose:p,createdAt:new Date().toISOString()});setJSON(APP.savingsKey,s);const m=getMoneyState();recalcMoney(m);setJSON(APP.moneyKey,m);renderSavings()}
function removeSavings(i){const s=getSavings();s.splice(i,1);setJSON(APP.savingsKey,s);const m=getMoneyState();recalcMoney(m);setJSON(APP.moneyKey,m);renderSavings()}
function getFamily(){return getJSON(APP.familyKey,[])}
function renderFamily(){const f=getFamily();renderShell(`<section class="section"><div class="card"><h1>❤️ ${esc(t("FAMILIA","FAMILY"))}</h1><p>${esc(t("Guarda a quién quieres ayudar y cuánto piensas separar. Es una referencia para organizarte.","Keep a reference of who you want to help and how much you plan to set aside."))}</p><label>${esc(t("Nombre o apodo","Name or nickname"))}</label><input id="familyName" maxlength="80"><label>${esc(t("País","Country"))}</label><select id="familyCountry"><option value="">${esc(t("Elige un país","Choose a country"))}</option>${(APP.config?.countries||[]).map(c=>{const id=String(c.id||c.code||"").toUpperCase();return`<option value="${id}">${esc(c.name?.[APP.lang]||c.name?.es||id)}</option>`}).join("")}</select><label>${esc(t("¿Cuánto quieres ayudar?","How much do you want to help with?"))}</label><input id="familyAmount" type="number" min="0" step=".01"><button class="btn" onclick="saveFamily()">${esc(t("GUARDAR","SAVE"))}</button></div><div class="list">${f.length?f.map((x,i)=>`<div class="card"><b>${esc(x.name)}</b><p>${esc(countryName(x.country))}</p><strong>${money(x.amount)}</strong><p class="small">${esc(t("Cantidad que has pensado separar.","Amount you planned to set aside."))}</p><button class="btn danger small" onclick="removeFamily(${i})">${esc(t("Borrar","Delete"))}</button></div>`).join(""):`<div class="empty">${esc(t("Aquí aparecerá la familia que quieras recordar.","Family references you add will appear here."))}</div>`}</div></section>`,t("Familia","Family"))}
function saveFamily(){const n=(document.getElementById("familyName")?.value||"").trim(),c=document.getElementById("familyCountry")?.value||"",a=num(document.getElementById("familyAmount")?.value);if(!n||!c){showError(t("Escribe un nombre y un país.","Enter a name and country."));return}const f=getFamily();f.push({name:n,country:c,amount:a,createdAt:new Date().toISOString()});setJSON(APP.familyKey,f);renderFamily()}
function removeFamily(i){const f=getFamily();f.splice(i,1);setJSON(APP.familyKey,f);renderFamily()}
function getPlans(){return getJSON(APP.plansKey,[])}
function renderGoals(){const p=getPlans();renderShell(`<section class="section"><div class="card"><h1>🛒 ${esc(t("QUIERO","I WANT"))}</h1><p>${esc(t("Una meta no es un gasto de hoy. Es algo que quieres conseguir y para lo que puedes ir guardando dinero.","A goal is not today's expense. It is something you want to achieve and can save toward."))}</p><label>${esc(t("¿Qué quieres lograr?","What do you want to achieve?"))}</label><input id="planName" maxlength="120"><label>${esc(t("¿Cuánto necesitas?","How much do you need?"))}</label><input id="planTarget" type="number" min=".01" step=".01"><label>${esc(t("¿Ya tienes algo guardado para eso?","Do you already have something saved for it?"))}</label><input id="planSaved" type="number" min="0" step=".01"><button class="btn" onclick="savePlan()">${esc(t("GUARDAR META","SAVE GOAL"))}</button></div><div class="list">${p.length?p.map((x,i)=>{const left=Math.max(0,num(x.target)-num(x.saved));return`<div class="card"><h3>${esc(x.name)}</h3><p>${esc(t("Meta","Goal"))}: <b>${money(x.target)}</b></p><p>${esc(t("Guardado","Saved"))}: <b>${money(x.saved)}</b></p><p>${esc(t("Falta","Left"))}: <b>${money(left)}</b></p><p class="small">${esc(t("Ese número te dice cuánto falta para llegar a la cantidad que quieres.","That number tells you how much remains to reach your target."))}</p><button class="btn danger small" onclick="removePlan(${i})">${esc(t("Borrar","Delete"))}</button></div>`}).join(""):`<div class="empty">${esc(t("Todavía no tienes una meta guardada.","You do not have a saved goal yet."))}</div>`}</div></section>`,t("QUIERO","I WANT"))}
function savePlan(){const n=(document.getElementById("planName")?.value||"").trim(),target=num(document.getElementById("planTarget")?.value),saved=num(document.getElementById("planSaved")?.value);if(!n||target<=0){showError(t("Escribe la meta y la cantidad que necesitas.","Enter the goal and the amount you need."));return}const p=getPlans();p.push({name:n,target,saved,createdAt:new Date().toISOString()});setJSON(APP.plansKey,p);renderGoals()}
function removePlan(i){const p=getPlans();p.splice(i,1);setJSON(APP.plansKey,p);renderGoals()}
function renderPuedo(){const m=getMoneyState();recalcMoney(m);setJSON(APP.moneyKey,m);const base=num(m.have)+num(m.incomeTotal),a=num(m.available);const title=a>=0?t("Esto es lo que puedes considerar disponible.","This is what you can consider available."):t("Tus compromisos son mayores que el dinero registrado.","Your commitments are greater than the money recorded.");const explain=a>=0?t(`Tienes ${money(a)} que todavía no has asignado a esos gastos o metas. No significa que tengas que gastarlo. Significa que, con los datos que pusiste, eso es lo que queda libre.`,`You have ${money(a)} that you have not assigned to those expenses or goals yet. It does not mean you must spend it. It means that, with the data you entered, that is what remains free.`):t(`Te faltan ${money(Math.abs(a))} para cubrir todo lo que registraste. Antes de aumentar un gasto o una remesa, revisa qué puedes cambiar.`,`You are ${money(Math.abs(a))} short of covering everything you recorded. Before increasing spending or a transfer, review what you can change.`);renderShell(`<section class="section"><div class="card"><h1>📅 ${esc(t("PUEDO","I CAN"))}</h1><p>${esc(t("Aquí no adivinamos. Tomamos lo que anotaste y te enseñamos qué queda.","We do not guess. We use what you recorded and show what remains."))}</p><div class="balance-grid"><div class="balance"><small>${esc(t("Tengo + gano","Have + earn"))}</small><b>${money(base)}</b><span>${esc(t("Dinero que registraste disponible o que entra.","Money you recorded as available or coming in."))}</span></div><div class="balance"><small>${esc(t("Gastos","Expenses"))}</small><b>${money(m.expenseTotal)}</b><span>${esc(t("Dinero que sale para pagar cosas.","Money that leaves to pay for things."))}</span></div><div class="balance"><small>${esc(t("Ahorro","Savings"))}</small><b>${money(m.savingsTotal)}</b><span>${esc(t("Dinero que apartaste.","Money you set aside."))}</span></div><div class="balance"><small>${esc(t("Me queda","Left"))}</small><b>${money(a)}</b><span>${esc(t("Después de lo que ya registraste.","After what you already recorded."))}</span></div></div><div class="notice"><h3>${esc(title)}</h3><p>${esc(explain)}</p></div><button class="btn" onclick="renderHago()">${esc(t("DIME QUÉ HAGO AHORA","TELL ME WHAT TO DO NOW"))}</button></div></section>`,t("PUEDO","I CAN"))}
function renderHago(){const m=getMoneyState();recalcMoney(m);setJSON(APP.moneyKey,m);const a=num(m.available);let text,action;if(a>0){text=t(`Tienes ${money(a)} disponibles según lo que registraste. Puedes decidir si una parte va a una meta, a una ayuda familiar o a una remesa. Antes de comprometerlo, revisa que no lo necesites para un gasto cercano.`,`You have ${money(a)} available based on what you recorded. You can decide whether part goes to a goal, family help, or a remittance. Before committing it, make sure you do not need it for an upcoming expense.`);action=`renderRemittance()`}else{text=t(`Ahora mismo no aparece dinero libre en tus registros. Eso no es un fracaso. Solo nos dice que primero conviene revisar qué entra y qué sale.`,`Right now your records do not show free money. That is not a failure. It simply means it may help to review what comes in and what goes out first.`);action=`renderPuedo()`}renderShell(`<section class="section"><div class="card"><h1>✅ ${esc(t("HAGO","I DO"))}</h1><p>${esc(t("No te dejamos con el número. Te damos el siguiente paso.","We do not leave you with a number. We give you the next step."))}</p><div class="notice"><h2>${esc(t("TU SIGUIENTE PASO","YOUR NEXT STEP"))}</h2><p>${esc(text)}</p></div><button class="btn" onclick="${action}">${esc(a>0?t("PREPARAR MI REMESA","PREPARE MY TRANSFER"):t("REVISAR MIS NÚMEROS","REVIEW MY NUMBERS"))}</button><button class="btn secondary" onclick="renderHome()">${esc(t("VOLVER A MI INICIO","BACK HOME"))}</button></div></section>`,t("HAGO","I DO"))}
function renderRemittance(p={}){const s=APP.session||{},amount=s.amount??p.amount??"",country=s.destination_country||p.destination_country||"";renderShell(`<section class="section"><div class="card"><h1>💸 ${esc(t("PREPARAR MI REMESA","PREPARE MY TRANSFER"))}</h1><p>${esc(t("Te preguntamos poco a poco. Cada respuesta sirve para decidir el siguiente paso.","We ask one step at a time. Each answer helps decide the next step."))}</p><label>${esc(t("¿Cuánto quieres enviar?","How much do you want to send?"))}</label><input id="sendAmount" type="number" min=".01" max="1000000" step=".01" value="${esc(amount)}"><p class="small">${esc(t("Esta cantidad nos permite revisar si encaja con el dinero que has registrado.","This amount lets us check whether it fits the money you recorded."))}</p><label>${esc(t("¿A qué país?","Which country?"))}</label><select id="sendCountry"><option value="">${esc(t("Elige el país","Choose country"))}</option>${(APP.config?.countries||[]).map(c=>{const id=String(c.id||c.code||"").toUpperCase();return`<option value="${id}" ${id===country?"selected":""}>${esc(c.name?.[APP.lang]||c.name?.es||id)}</option>`}).join("")}</select><label>${esc(t("¿Qué es más importante para ti?","What matters most to you?"))}</label><select id="sendPriority"><option value="">${esc(t("Todavía no sé","Not sure yet"))}</option>${[["recipient_gets_more","Que reciba más"],["fastest","Que llegue rápido"],["save","Pagar menos"],["balanced","Un poco de todo"]].map(x=>`<option value="${x[0]}">${esc(t(x[1],x[1]))}</option>`).join("")}</select><label>${esc(t("¿Es urgente?","Is it urgent?"))}</label><select id="sendUrgency"><option value="">${esc(t("No estoy seguro","Not sure"))}</option><option value="true">${esc(t("Sí","Yes"))}</option><option value="false">${esc(t("No","No"))}</option></select><label>${esc(t("¿Cómo quieres que reciba?","How should the recipient receive it?"))}</label><select id="sendDelivery"><option value="">${esc(t("Todavía no sé","Not sure yet"))}</option>${(APP.config?.delivery_methods||[]).map(x=>`<option value="${esc(x.id)}">${esc(methodLabel(x))}</option>`).join("")}</select><label>${esc(t("¿Cómo vas a pagar?","How will you pay?"))}</label><select id="sendPayment"><option value="">${esc(t("Todavía no sé","Not sure yet"))}</option>${(APP.config?.payment_methods||[]).map(x=>`<option value="${esc(x.id)}">${esc(methodLabel(x))}</option>`).join("")}</select><div id="sendMeaning"></div><button class="btn" onclick="compare()">${esc(t("VER LAS 4 REMESADORAS","SEE THE 4 PROVIDERS"))}</button></div></section>`,t("Preparar remesa","Prepare transfer"));document.getElementById("sendAmount")?.addEventListener("input",explainSend);explainSend()}
function explainSend(){const b=document.getElementById("sendMeaning");if(!b)return;const a=num(document.getElementById("sendAmount")?.value),m=getMoneyState(),av=num(m.available);if(!a){b.innerHTML="";return}let s=a<=av||av<=0?t(`Quieres enviar ${money(a)}. Primero veremos si esa cantidad cabe en lo que has registrado.`,`You want to send ${money(a)}. First we will see whether that amount fits what you recorded.`):t(`Quieres enviar ${money(a)} y tienes ${money(av)} disponibles según tus registros. Eso significa que el envío supera lo que aparece libre. Antes de comprometerlo, revisemos tus números.`,`You want to send ${money(a)} and you have ${money(av)} available according to your records. That means the transfer is above what appears free. Before committing it, let's review your numbers.`);b.innerHTML=`<div class="notice"><p>${esc(s)}</p></div>`}
async function compare(){const amount=num(document.getElementById("sendAmount")?.value),destination=document.getElementById("sendCountry")?.value||"";if(amount<=0){showError(t("Dime cuánto quieres enviar.","Tell me how much you want to send."));return}if(!destination){showError(t("Dime a qué país va el dinero.","Tell me which country the money is going to."));return}try{if(!(await verifyAccess())){renderGate();return}if(!APP.session&&!(await startService()))return;const u=document.getElementById("sendUrgency")?.value||"";const d=await api("/api/need",{method:"POST",body:JSON.stringify({session_id:APP.session.session_id,language:APP.lang,need_type:"remittance",amount,destination_country:destination,priority:document.getElementById("sendPriority")?.value||null,urgency:u===""?null:u==="true",delivery_method:document.getElementById("sendDelivery")?.value||null,payment_method:document.getElementById("sendPayment")?.value||null})});APP.session=d.session;renderLoading();const r=await api(`/api/session/${APP.session.session_id}/compare`,{method:"POST"});APP.session.available_providers=r.available_providers||[];APP.session.verified_results=r.results||[];renderComparison(r)}catch(e){showError(e.message)}}
function renderLoading(){renderShell(`<section class="section"><div class="card center"><div class="spinner"></div><h2>${esc(t("Estamos preparando la información","We are preparing the information"))}</h2><p>${esc(t("No vamos a inventar un precio, una tasa ni un tiempo.","We will not invent a price, rate, or delivery time."))}</p></div></section>`,t("Un momento","One moment"))}
function providerCard(p){const id=p.provider_id||p.id||"",r=(APP.session?.verified_results||[]).find(x=>x.provider_id===id),verified=Boolean(p.commercial_verified||p.commercial_status==="verified"||r?.status==="verified"),url=p.continue_url||p.official_site||p.official_urls?.send_money||p.official_urls?.site,payment=(p.payment_methods||[]).map(methodLabel).filter(Boolean),delivery=(p.delivery_methods||[]).map(methodLabel).filter(Boolean),name=String(p.provider_name||p.name||id).toUpperCase();return`<article class="provider-card"><div class="provider-head"><h2>${esc(name)}</h2><span class="provider-status ${verified?"verified":""}">${esc(verified?t("Dato confirmado","Confirmed data"):t("Confirma hoy","Confirm today"))}</span></div>${verified&&r?`<div class="provider-data"><div class="metric"><small>${esc(t("Costo","Cost"))}</small><b>${r.fee!=null?money(r.fee):esc(t("No indicado","Not shown"))}</b></div><div class="metric"><small>${esc(t("Tasa","Rate"))}</small><b>${esc(r.exchange_rate??t("No indicada","Not shown"))}</b></div><div class="metric"><small>${esc(t("Recibe","Receives"))}</small><b>${r.recipient_amount!=null?money(r.recipient_amount):esc(t("No indicado","Not shown"))}</b></div><div class="metric"><small>${esc(t("Entrega","Delivery"))}</small><b>${esc(r.estimated_delivery??r.delivery_time??t("No indicado","Not shown"))}</b></div></div>`:`<div class="notice"><p>${esc(t("No te damos un precio inventado. Este dato puede cambiar. Abre el sitio oficial para ver el costo, la tasa, el tiempo y la disponibilidad de hoy.","We will not give you an invented price. This can change. Open the official site to see today's cost, rate, timing, and availability."))}</p></div>`}${payment.length?`<p class="small"><b>${esc(t("Puedes pagar con:","You can pay with:"))}</b> ${esc(payment.join(", "))}</p>`:""}${delivery.length?`<p class="small"><b>${esc(t("Puede recibir por:","Recipient can receive by:"))}</b> ${esc(delivery.join(", "))}</p>`:""}${url?`<button class="btn" onclick="selectProvider('${esc(id)}')">${esc(t("REVISAR ESTA OPCIÓN","REVIEW THIS OPTION"))}</button>`:""}</article>`}
function renderComparison(data){const providers=data.available_providers||[],verified=num(data.verified_count||0);renderShell(`<section class="section"><div class="card"><h1>${esc(t("LAS 4 REMESADORAS","THE 4 PROVIDERS"))}</h1><p>${esc(t(`Quieres enviar ${money(data.amount)} a ${countryName(data.destination_country)}. Aquí tienes las opciones en un solo lugar.`,`You want to send ${money(data.amount)} to ${countryName(data.destination_country)}. Here are the options in one place.`))}</p>${verified?`<div class="notice"><b>${esc(t(`${verified} opción(es) tiene(n) datos actuales confirmados.`,` ${verified} option(s) have current confirmed data.`))}</b><p>${esc(data.explanation||"")}</p></div>`:`<div class="notice"><b>${esc(t("Los datos de hoy deben confirmarse.","Today's details must be confirmed."))}</b><p>${esc(t("No dejamos un número que pueda estar viejo. Cada remesadora puede cambiar costo, tasa, tiempo o disponibilidad. Puedes abrir la página oficial y comprobarlo antes de enviar.","We do not leave you with a number that may be outdated. Each provider can change cost, rate, timing, or availability. You can open the official page and check before sending."))}</p></div>`}${providers.length?`<div class="grid">${providers.map(providerCard).join("")}</div>`:`<div class="empty">${esc(t("No encontramos estas opciones para ese destino.","We did not find these options for that destination."))}</div>`}<button class="btn secondary" onclick="renderRemittance()">${esc(t("CAMBIAR LO QUE NECESITO","CHANGE MY NEED"))}</button><button class="btn secondary" onclick="renderHome()">${esc(t("VOLVER","BACK"))}</button></div></section>`,t("Comparar","Compare"))}
async function selectProvider(id){try{const d=await api(`/api/session/${APP.session.session_id}/select/${encodeURIComponent(id)}`,{method:"POST"});APP.session=d.session;renderFinalCheck()}catch(e){showError(e.message)}}
async function renderFinalCheck(){if(!APP.session?.selected_option){showError(t("Primero elige una remesadora.","Choose a provider first."));return}const o=APP.session.selected_option;renderShell(`<section class="section"><div class="card"><h1>${esc(String(o.provider_name||"").toUpperCase())}</h1><p>${esc(t("Antes de continuar, hacemos una última revisión para que no te vayas con una duda importante.","Before you continue, we do one last review so you do not leave with an important question."))}</p><label>${esc(t("¿Ya tienes los datos de la persona que recibirá el dinero?","Do you have the recipient's information?"))}</label><select id="recipientReady"><option value="">${esc(t("Todavía no","Not yet"))}</option><option value="true">${esc(t("Sí","Yes"))}</option><option value="false">${esc(t("No","No"))}</option></select><label>${esc(t("¿Quieres confirmar la cantidad una vez más?","Do you want to confirm the amount one more time?"))}</label><input id="finalAmount" type="number" min=".01" step=".01" value="${esc(APP.session.amount||"")}"><button class="btn" onclick="finishCheck()">${esc(t("REVISAR ANTES DE CONTINUAR","REVIEW BEFORE CONTINUING"))}</button><div id="finalResult"></div></div></section>`,t("Última revisión","Final review"))}
async function finishCheck(){const amount=num(document.getElementById("finalAmount")?.value),ready=document.getElementById("recipientReady")?.value==="true";if(amount<=0){showError(t("Revisa la cantidad.","Review the amount."));return}try{const d=await api(`/api/session/${APP.session.session_id}/final-check`,{method:"POST",body:JSON.stringify({language:APP.lang,provider_id:APP.session.selected_option.provider_id||APP.session.selected_option.id,amount,currency:"USD",destination:APP.session.destination_country,delivery_method:null,payment_method:null,recipient_information_entered:ready,checks:[]})});const o=APP.session.selected_option,url=o.continue_url||o.official_site||o.official_urls?.send_money||o.official_urls?.site,b=document.getElementById("finalResult"),title=d.ready_to_continue?t("YA ESTÁS LISTO PARA REVISAR","YOU ARE READY TO REVIEW"):t("FALTA REVISAR ALGO","SOMETHING STILL NEEDS REVIEW"),openLabel=t("ABRIR","OPEN")+" "+String(o.provider_name||"REMESADORA").toUpperCase();b.innerHTML=`<div class="notice"><h3>${esc(title)}</h3><p>${esc(d.message||"")}</p>${(d.requirements||[]).length?`<p><b>${esc(t("Antes de continuar:","Before continuing:"))}</b> ${(d.requirements||[]).map(x=>esc(methodLabel(x))).join(", ")}</p>`:""}<p>${esc(t("La remesadora oficial mostrará las condiciones finales. Revisa antes de confirmar el envío.","The official provider will show the final conditions. Review them before confirming the transfer."))}</p></div>${url?`<button class="btn" onclick="openOfficial('${esc(url)}')">${esc(openLabel)}</button>`:""}<button class="btn secondary" onclick="renderComparisonFromSession()">${esc(t("VER LAS 4 REMESADORAS","SEE ALL 4 PROVIDERS"))}</button>`}catch(e){showError(e.message)}}
function openOfficial(url){if(!/^https:\/\//i.test(url)){showError(t("No pude abrir ese sitio oficial.","I could not open that official site."));return}window.open(url,"_blank","noopener,noreferrer")}
function renderComparisonFromSession(){renderComparison({available_providers:APP.session?.available_providers||[],verified_count:(APP.session?.verified_results||[]).length,results_available:(APP.session?.verified_results||[]).length>0,amount:APP.session?.amount,destination_country:APP.session?.destination_country,explanation:t("Son las opciones de tu sesión actual.","These are the options from your current session.")})}
function renderQuickGuide(){const steps=[t("1. Elige el país.","1. Choose the country."),t("2. Escribe cuánto quieres enviar.","2. Enter how much you want to send."),t("3. Decide cómo quieres que reciba.","3. Decide how the recipient should receive."),t("4. Mira las cuatro remesadoras.","4. See the four providers."),t("5. Revisa costo, tasa, cantidad que recibe y tiempo en la página oficial.","5. Review cost, rate, recipient amount, and timing on the official site."),t("6. Solo después decide si continúas.","6. Only then decide whether to continue.")];renderShell(`<section class="section"><div class="card"><h1>🧭 ${esc(t("GUÍA RÁPIDA","QUICK GUIDE"))}</h1><p>${esc(t("Si nunca has enviado dinero, sigue estos pasos sin correr.","If you have never sent money, follow these steps without rushing."))}</p><div class="result-list">${steps.map(x=>`<div><b>${esc(x)}</b><p>${esc(t("Si algo no entiendes, detente y pregúntalo antes de pagar.","If you do not understand something, stop and ask before paying."))}</p></div>`).join("")}</div><button class="btn" onclick="renderRemittance()">${esc(t("EMPEZAR MI REMESA","START MY TRANSFER"))}</button></div></section>`,t("Guía rápida","Quick guide"))}
const lessons=["before_you_start","choose_destination","enter_amount","understand_recipient_amount","choose_delivery","choose_payment","recipient_information","review_before_sending","complete_with_provider","after_sending"];
const lessonText={before_you_start:["Antes de empezar","Ten claro cuánto quieres enviar y a quién. Nunca compartas contraseñas, códigos ni datos de seguridad."],choose_destination:["Elegir país","El país importa porque cambia las opciones disponibles y las condiciones."],enter_amount:["Escribir cantidad","La cantidad es el punto de partida para revisar si el envío encaja con tus números."],understand_recipient_amount:["Entender cuánto recibe","La cantidad que tú envías no siempre es la misma que recibe la otra persona. Revisa el resultado final."],choose_delivery:["Elegir cómo recibe","Puede haber distintas formas de entrega. Elige la que realmente necesita la persona."],choose_payment:["Elegir cómo pagas","Usa solo un medio de pago que reconozcas y revisa la pantalla final antes de confirmar."],recipient_information:["Datos de quien recibe","Escribe solo los datos que el proveedor oficial te pida. No compartas claves con nadie."],review_before_sending:["Revisar antes de enviar","Mira nombre, cantidad, costo, tasa, cantidad recibida y condiciones."],complete_with_provider:["Completar con la remesadora","REMESAS te lleva al sitio oficial. Allí haces el proceso directamente con el proveedor."],after_sending:["Después de enviar","Guarda el comprobante y revisa que la persona reciba el dinero según la información que te dio el proveedor."]};
function renderLearn(){renderShell(`<section class="section"><div class="card"><h1>📖 ${esc(t("APRENDER","LEARN"))}</h1><p>${esc(t("Aprende una cosa a la vez. No necesitas saber palabras de banco para entender el proceso.","Learn one thing at a time. You do not need banking words to understand the process."))}</p><div class="result-list">${lessons.map((id,i)=>{const x=lessonText[id];return`<button class="choice" onclick="showLesson(${i})"><b>${esc(x[0])}</b><small>${esc(x[1])}</small></button>`}).join("")}</div><button class="btn secondary" onclick="exportLearningPDF()">${esc(t("GUARDAR GUÍA EN PDF","SAVE GUIDE AS PDF"))}</button></div></section>`,t("Aprender","Learn"))}
function showLesson(i){const id=lessons[i],x=lessonText[id]||lessonText.before_you_start;renderShell(`<section class="section"><div class="card"><h1>${esc(x[0])}</h1><p>${esc(x[1])}</p><div class="notice"><b>${esc(t("¿Por qué importa?","Why does it matter?"))}</b><p>${esc(t("Porque entender cada paso reduce la posibilidad de equivocarte por miedo, prisa o confusión.","Because understanding each step reduces the chance of mistakes caused by fear, haste, or confusion."))}</p></div>${i<lessons.length-1?`<button class="btn" onclick="showLesson(${i+1})">${esc(t("SIGUIENTE","NEXT"))}</button>`:`<button class="btn" onclick="renderRemittance()">${esc(t("YA ENTIENDO: PREPARAR REMESA","I UNDERSTAND: PREPARE TRANSFER"))}</button>`}<button class="btn secondary" onclick="renderLearn()">${esc(t("VER APRENDER","BACK TO LEARN"))}</button></div></section>`,t("Aprender","Learn"))}
function renderHelp(){const topics=APP.config?.help_topics||[];const fallback=[{id:"money",title:t("¿Qué significa un número?","What does a number mean?"),answer:t("Un número siempre debe decirte qué representa, de dónde salió y qué cambia. Si ves un número sin explicación, pregunta antes de usarlo.","A number should tell you what it represents, where it came from, and what changes. If you see a number without an explanation, ask before using it.")},{id:"remittance",title:t("¿Cómo envío dinero?","How do I send money?"),answer:t("Primero define cantidad y país. Después revisa las cuatro remesadoras y confirma las condiciones directamente con la elegida.","First define amount and country. Then review the four providers and confirm the conditions directly with the one you choose.")},{id:"pdf",title:t("¿Cómo recupero mis datos?","How do I recover my data?"),answer:t("Entra tu PDF de REMESAS desde la opción ENTRAR PDF. La aplicación intenta recuperar los datos que guardaste.","Use ENTRAR PDF to bring back your REMESAS PDF. The app will try to recover the information you saved.")}];const list=topics.length?topics.map(x=>({id:x.id,title:x.title?.[APP.lang]||x.title,answer:x.answer?.[APP.lang]||x.answer})):fallback;renderShell(`<section class="section"><div class="card"><h1>❓ ${esc(t("AYUDA","HELP"))}</h1><p>${esc(t("No hay preguntas tontas. Pregunta hasta entender.","There are no silly questions. Ask until you understand."))}</p>${list.map(x=>`<button class="choice" onclick="showHelpTopic('${esc(x.id)}')"><b>${esc(x.title)}</b></button>`).join("")}<button class="btn secondary" onclick="renderAbout()">${esc(t("¿QUÉ ES REMESAS?","WHAT IS REMESAS?"))}</button></div></section>`,t("Ayuda","Help"))}
function showHelpTopic(id){const topics=APP.config?.help_topics||[],raw=topics.find(x=>x.id===id);const x=raw?{title:raw.title?.[APP.lang]||raw.title,answer:raw.answer?.[APP.lang]||raw.answer}:{title:t("Ayuda","Help"),answer:t("Pregunta de nuevo con tus palabras y te guiaremos paso a paso.","Ask again in your own words and we will guide you step by step.")};renderShell(`<section class="section"><div class="card"><h1>${esc(x.title)}</h1><p>${esc(x.answer)}</p><button class="btn" onclick="renderHelp()">${esc(t("VOLVER A AYUDA","BACK TO HELP"))}</button></div></section>`,t("Ayuda","Help"))}
function renderAbout(){renderShell(`<section class="section"><div class="card"><h1>${esc(t("REMESAS: claro y sencillo","REMESAS: clear and simple"))}</h1><p>${esc(t("REMESAS te ayuda a entender, organizar y preparar decisiones sobre tu dinero. Te explica los números con palabras sencillas y te lleva a las remesadoras oficiales cuando necesitas confirmar algo.","REMESAS helps you understand, organize, and prepare decisions about your money. It explains numbers in simple words and takes you to official providers when you need to confirm something."))}</p><h2>${esc(t("Lo que sí hacemos","What we do"))}</h2><p>${esc(t("Organizamos tus registros, hacemos cálculos con lo que tú pones, enseñamos el proceso de una remesa y reunimos las cuatro remesadoras para que puedas revisarlas.","We organize your records, calculate with what you enter, teach the remittance process, and bring the four providers together so you can review them."))}</p><h2>${esc(t("Lo que no hacemos","What we do not do"))}</h2><p>${esc(t("No recibimos ni enviamos dinero, no abrimos cuentas por ti, no pedimos contraseñas ni códigos de seguridad y no prometemos una tarifa, tasa, tiempo o disponibilidad que no esté confirmada.","We do not receive or send money, open accounts for you, ask for passwords or security codes, or promise a fee, rate, timing, or availability that is not confirmed."))}</p><h2>${esc(t("Tus datos","Your data"))}</h2><p>${esc(t("Tus registros personales se conservan en este dispositivo hasta que tú los borres. Puedes guardar una copia en PDF y volver a entrarla cuando quieras.","Your personal records stay on this device until you delete them. You can save a PDF copy and bring it back when you want."))}</p><button class="btn danger" onclick="deleteLocalData()">${esc(t("BORRAR MIS DATOS","DELETE MY DATA"))}</button></div></section>`,t("Privacidad","Privacy"))}
function renderGate(){app.innerHTML=`<div class="app-shell"><main><section class="hero"><h1>REMESAS</h1><h2>${esc(t("TU DINERO, MÁS CLARO","YOUR MONEY, CLEARER"))}</h2><p>${esc(t("Un espacio sencillo para organizar tu dinero y preparar una remesa con calma.","A simple place to organize your money and prepare a remittance calmly."))}</p><div class="card"><h2>${esc(t("ACCESO AL SERVICIO","SERVICE ACCESS"))}</h2><p>${esc(t("Pago único de $10.99. Acceso durante 20 minutos.","One-time payment of $10.99. Access for 20 minutes."))}</p><button class="btn" onclick="startPaidAccess()">💳 ${esc(t("PAGAR $10.99 Y ENTRAR","PAY $10.99 AND ENTER"))}</button><button class="btn secondary" onclick="showServiceInfo()">${esc(t("VER QUÉ INCLUYE","SEE WHAT IS INCLUDED"))}</button></div></section></main></div>`;let taps=0,timer;app.addEventListener("click",()=>{taps++;clearTimeout(timer);timer=setTimeout(()=>taps=0,800);if(taps>=3){taps=0;showAdmin();}})}
async function showServiceInfo(){let d;try{d=await api("/api/service/info")}catch{d={price:10.99,currency:"USD",minutes:20}}renderShell(`<section class="section"><div class="card"><h1>${esc(t("¿Cómo funciona?","How does it work?"))}</h1><p>${esc(t(`Tienes acceso temporal para organizar tu dinero, preparar una remesa, aprender el proceso, comparar opciones y hacer una revisión final. El acceso dura ${d.minutes||20} minutos.`,`You get temporary access to organize your money, prepare a remittance, learn the process, compare options, and do a final review. Access lasts ${d.minutes||20} minutes.`))}</p><h2>${money(d.price||10.99)}</h2><p>${esc(t("Es un pago único por este acceso. No es una suscripción.","It is a one-time payment for this access. It is not a subscription."))}</p><button class="btn" onclick="startPaidAccess()">${esc(t("CONTINUAR","CONTINUE"))}</button></div></section>`,t("Acceso","Access"))}
async function startPaidAccess(){try{const s=await serviceStatus();if(s.active){APP.access=token();await startService();renderHome();return}const d=await api("/api/create-checkout-session",{method:"POST",body:JSON.stringify({language:APP.lang})});if(d.url){window.location.href=d.url;return}if(d.checkout_url){window.location.href=d.checkout_url;return}showError(t("No se pudo abrir el pago.","The payment page could not be opened."))}catch(e){showError(e.message)}}
function showAdmin(){const old=document.getElementById("adminModal");if(old)old.remove();const d=document.createElement("div");d.id="adminModal";d.className="modal-backdrop";d.innerHTML=`<div class="modal"><div class="modal-head"><h2>REMESAS</h2><button class="close" onclick="this.closest('.modal-backdrop').remove()">×</button></div><label>${esc(t("Usuario","Username"))}</label><input id="adminUser" autocomplete="username"><label>${esc(t("Clave","Password"))}</label><input id="adminPass" type="password" autocomplete="current-password"><button class="btn" onclick="adminLogin()">${esc(t("ENTRAR","ENTER"))}</button></div>`;document.body.appendChild(d)}
async function adminLogin(){try{const d=await api("/api/access/admin",{method:"POST",body:JSON.stringify({username:document.getElementById("adminUser")?.value||"",password:document.getElementById("adminPass")?.value||""})});if(!d.access_token)throw new Error(t("No se pudo abrir el acceso.","Access could not be opened."));APP.access=d.access_token;localStorage.setItem("remesas_access_v4",APP.access);document.getElementById("adminModal")?.remove();await startService();renderHome()}catch(e){showError(t("El acceso no pudo abrirse. Revisa los datos.","Access could not be opened. Check the information."))}}
function moneyPDFData(){const m=getMoneyState();return{version:APP.version,kind:"REMESAS_MONEY",created_at:new Date().toISOString(),money:m,expenses:getExpenses(),savings:getSavings(),family:getFamily(),plans:getPlans()}}
function printPDF(title,body){const w=window.open("","_blank");if(!w){showError(t("Permite la ventana para guardar tu PDF.","Allow the window so you can save your PDF."));return}w.document.write(`<!doctype html><html lang="${APP.lang}"><head><meta charset="utf-8"><title>${esc(title)}</title><style>body{font-family:Arial,sans-serif;max-width:760px;margin:30px auto;padding:20px;color:#172033}h1{margin-bottom:6px}h2{margin-top:26px}section{border:1px solid #ddd;border-radius:12px;padding:16px;margin:12px 0}p{line-height:1.5}.n{font-size:22px;font-weight:700}.muted{color:#667085;font-size:13px}</style></head><body>${body}<p class="muted">${esc(t("REMESAS · May Roga LLC · Este documento es un registro personal de lo que escribiste. No es un documento bancario ni una declaración de impuestos.","REMESAS · May Roga LLC · This is a personal record of what you entered. It is not a bank document or tax return."))}</p><script>window.onload=()=>setTimeout(()=>print(),300)</script></body></html>`);w.document.close()}
function exportMoneyPDF(){const d=moneyPDFData(),m=d.money,body=`<h1>REMESAS — ${esc(t("MIS DATOS","MY DATA"))}</h1><p>${esc(new Date(d.created_at).toLocaleString(APP.lang==="es"?"es-US":"en-US"))}</p><section><h2>TENGO</h2><div class="n">${money(m.have)}</div><p>${esc(t("Dinero disponible que registraste como punto de partida.","Available money you recorded as your starting point."))}</p></section><section><h2>GANO</h2><div class="n">${money(m.monthlyIncome)}</div><p>${esc(t("Entrada mensual equivalente según la frecuencia que registraste.","Monthly equivalent based on the frequency you recorded."))}</p></section><section><h2>GASTO</h2><div class="n">${money(m.expenseTotal)}</div><p>${esc(t("Gastos mensuales que aparecen en tus registros.","Monthly expenses in your records."))}</p></section><section><h2>AHORRO</h2><div class="n">${money(m.savingsTotal)}</div><p>${esc(t("Dinero que registraste como apartado para tus metas.","Money you recorded as set aside for your goals."))}</p></section><section><h2>PUEDO</h2><div class="n">${money(m.available)}</div><p>${esc(t("Cantidad que queda según los datos que registraste después de las salidas anotadas.","Amount left according to the information you recorded after the listed outflows."))}</p></section><section><h2>GASTOS REGISTRADOS</h2>${d.expenses.map(x=>`<p>${esc(x.description)} — <b>${money(x.amount)}</b></p>`).join("")||`<p>${esc(t("Ninguno.","None."))}</p>`}</section><section><h2>AHORROS</h2>${d.savings.map(x=>`<p>${esc(x.purpose)} — <b>${money(x.amount)}</b></p>`).join("")||`<p>${esc(t("Ninguno.","None."))}</p>`}</section><section><h2>${esc(t("FAMILIA","FAMILY"))}</h2>${d.family.map(x=>`<p>${esc(x.name)} — ${esc(countryName(x.country))} — <b>${money(x.amount)}</b></p>`).join("")||`<p>${esc(t("Ninguno.","None."))}</p>`}</section><section><h2>${esc(t("METAS","GOALS"))}</h2>${d.plans.map(x=>`<p>${esc(x.name)} — ${esc(t("Meta","Goal"))}: <b>${money(x.target)}</b> · ${esc(t("Guardado","Saved"))}: <b>${money(x.saved)}</b></p>`).join("")||`<p>${esc(t("Ninguna.","None."))}</p>`}</section><p class="muted">REMESAS_DATA:${btoa(unescape(encodeURIComponent(JSON.stringify(d))))}</p>`;printPDF(t("Mis datos REMESAS","My REMESAS data"),body)}
function exportLearningPDF(){const body=`<h1>REMESAS — ${esc(t("GUÍA PARA APRENDER","LEARNING GUIDE"))}</h1>${lessons.map(id=>{const x=lessonText[id];return`<section><h2>${esc(x[0])}</h2><p>${esc(x[1])}</p></section>`}).join("")}<p class="muted">${esc(t("Consulta siempre las condiciones actuales con la remesadora oficial.","Always check current conditions with the official provider."))}</p>`;printPDF(t("Guía REMESAS","REMESAS Guide"),body)}
function pickPDF(){const input=document.createElement("input");input.type="file";input.accept="application/pdf,.pdf";input.onchange=()=>{if(input.files?.[0])restorePDF(input.files[0])};input.click()}
async function restorePDF(file){if(!/\.pdf$/i.test(file.name)&&file.type!=="application/pdf"){showError(t("Elige un archivo PDF.","Choose a PDF file."));return}renderShell(`<section class="section"><div class="card center"><div class="spinner"></div><h2>${esc(t("LEER MI PDF","READ MY PDF"))}</h2><p>${esc(t("Estamos buscando tus datos guardados para volver a ponerlos en su lugar.","We are looking for your saved information so we can put it back in place."))}</p></div></section>`,t("Recuperar","Recover"));try{const fd=new FormData();fd.append("file",file);let d=null;for(const u of ["/api/pdf/import","/api/pdf/restore","/api/import/pdf"]){try{const r=await fetch(u,{method:"POST",headers:headers({}),body:fd});if(r.ok){d=await r.json();break}}catch{}}if(d?.data)applyImportedData(d.data);else{const raw=await file.arrayBuffer();const text=new TextDecoder().decode(raw);const m=text.match(/REMESAS_DATA:([A-Za-z0-9+/=]+)/);if(m){try{const data=JSON.parse(decodeURIComponent(escape(atob(m[1]))));applyImportedData(data);return}catch{}}}if(!d?.data){renderShell(`<section class="section"><div class="card"><h1>${esc(t("NO PUDE RECUPERAR ESTE PDF","I COULD NOT RECOVER THIS PDF"))}</h1><p>${esc(t("Necesito el PDF que guardaste desde REMESAS. Si elegiste otro archivo, busca el PDF de REMESAS e inténtalo otra vez.","I need the PDF you saved from REMESAS. If you chose another file, find your REMESAS PDF and try again."))}</p><button class="btn" onclick="pickPDF()">${esc(t("ELEGIR OTRO PDF","CHOOSE ANOTHER PDF"))}</button><button class="btn secondary" onclick="renderHome()">${esc(t("VOLVER","BACK"))}</button></div></section>`,t("Recuperar","Recover"))}}catch(e){showError(t("No pude leer ese PDF. Conserva el archivo e inténtalo de nuevo.","I could not read that PDF. Keep the file and try again."))}}
function applyImportedData(data){if(!data||data.kind!=="REMESAS_MONEY"){showError(t("Este no parece ser un PDF de REMESAS.","This does not appear to be a REMESAS PDF."));return}if(data.money)setJSON(APP.moneyKey,data.money);if(Array.isArray(data.expenses))setJSON(APP.expensesKey,data.expenses);if(Array.isArray(data.savings))setJSON(APP.savingsKey,data.savings);if(Array.isArray(data.family))setJSON(APP.familyKey,data.family);if(Array.isArray(data.plans))setJSON(APP.plansKey,data.plans);const m=getMoneyState();recalcMoney(m);setJSON(APP.moneyKey,m);renderShell(`<section class="section"><div class="card"><h1>${esc(t("TUS DATOS HAN VUELTO","YOUR DATA IS BACK"))}</h1><p>${esc(t("Recuperamos tus registros y volvimos a calcular lo que tienes, lo que entra, lo que sale, lo que guardas y lo que queda.","We recovered your records and recalculated what you have, what comes in, what goes out, what you save, and what remains."))}</p><div class="notice"><h2>${money(m.available)}</h2><p>${esc(t("Este es el dinero que queda según la información recuperada y los registros actuales.","This is the money left according to the recovered information and current records."))}</p></div><button class="btn" onclick="renderPuedo()">${esc(t("VER MI DINERO","SEE MY MONEY"))}</button></div></section>`,t("Datos recuperados","Data recovered"))}
function understandNeed(){const el=document.getElementById("freeNeed"),text=(el?.value||"").trim();if(!text){showError(t("Escribe qué necesitas.","Write what you need."));return}const m=text.match(/(\$?\s?\d+(?:[.,]\d{1,2})?)/),countries=APP.config?.countries||[];let dest=null;for(const c of countries){const names=[c.id,c.code,c.name?.es,c.name?.en,...(c.aliases||[])].filter(Boolean).map(String);if(names.some(n=>text.toLowerCase().includes(n.toLowerCase()))){dest=String(c.id||c.code).toUpperCase();break}}if(m&&dest){beginParsedRemittance({amount:num(m[1].replace(/,/g,"")),destination_country:dest});return}if(/ahorr|guardar|meta|carro|casa|viaje|compr/i.test(text)){renderGoals();return}if(/gast|pagar|comida|renta|alquiler/i.test(text)){renderExpenses();return}renderHelp()}
function renderMoney(){const m=getMoneyState();recalcMoney(m);renderShell(`<section class="section"><div class="card"><h1>💰 ${esc(t("MI DINERO","MY MONEY"))}</h1><p>${esc(t("Aquí juntamos tus entradas y salidas para explicarte qué queda. No es una cuenta bancaria.","Here we combine your money coming in and going out to explain what remains. It is not a bank account."))}</p><div class="balance-grid"><div class="balance"><small>TENGO</small><b>${money(m.have)}</b><span>${esc(t("Lo que dices que tienes ahora.","What you say you have now."))}</span></div><div class="balance"><small>GANO</small><b>${money(m.monthlyIncome)}</b><span>${esc(t("Lo que entra en un mes equivalente.","What comes in during an equivalent month."))}</span></div><div class="balance"><small>GASTO</small><b>${money(m.expenseTotal)}</b><span>${esc(t("Lo que sale según tus registros.","What leaves according to your records."))}</span></div><div class="balance"><small>AHORRO</small><b>${money(m.savingsTotal)}</b><span>${esc(t("Lo que apartaste.","What you set aside."))}</span></div><div class="balance"><small>PUEDO</small><b>${money(m.available)}</b><span>${esc(t("Lo que queda después de lo registrado.","What remains after what you recorded."))}</span></div></div><div class="notice"><p>${esc(m.available>=0?t(`Te quedan ${money(m.available)} según tus registros. Este número no apareció solo: sale de lo que pusiste en TENGO, GANO, GASTO y AHORRO.`,`You have ${money(m.available)} left according to your records. This number did not appear by itself: it comes from what you entered in HAVE, EARN, SPEND, and SAVE.`):t(`Tus registros están ${money(Math.abs(m.available))} por encima del dinero que aparece disponible. Revisa qué gasto o meta puedes cambiar antes de comprometer más dinero.`,`Your records are ${money(Math.abs(m.available))} above the money shown as available. Review which expense or goal you can change before committing more money.`))}</p></div><button class="btn" onclick="renderPuedo()">${esc(t("EXPLICARME QUÉ PUEDO HACER","EXPLAIN WHAT I CAN DO"))}</button><button class="btn secondary" onclick="renderHago()">${esc(t("DIME EL SIGUIENTE PASO","TELL ME THE NEXT STEP"))}</button></div></section>`,t("Mi dinero","My money"))}
function renderWeek(){renderPeriod("weekly")}
function renderPeriod(period){const m=getMoneyState(),f=period==="weekly"?4.333333:period==="biweekly"?2.166667:1,inc=num(m.monthlyIncome)/f,exp=num(m.expenseTotal)/f,sav=num(m.savingsTotal)/f,a=inc-exp-sav;renderShell(`<section class="section"><div class="card"><h1>📆 ${esc(period==="weekly"?t("MI SEMANA","MY WEEK"):period==="biweekly"?t("MI QUINCENA","MY TWO WEEKS"):t("MI MES","MY MONTH"))}</h1><p>${esc(t("Una vista corta para saber cómo vas sin llenar la pantalla de números.","A short view so you know how you are doing without filling the screen with numbers."))}</p><div class="notice"><h2>${money(a)}</h2><p>${esc(t(`Después de lo que registraste para este periodo, quedan aproximadamente ${money(a)}. Es una referencia hecha con tus propios datos.`,`After what you recorded for this period, approximately ${money(a)} remains. It is a reference based on your own data.`))}</p></div><div class="result-list"><div><b>${esc(t("Entra","Comes in"))}: ${money(inc)}</b><small>${esc(t("Dinero que esperas recibir en este periodo.","Money you expect to receive in this period."))}</small></div><div><b>${esc(t("Sale","Goes out"))}: ${money(exp)}</b><small>${esc(t("Gastos registrados para este periodo.","Expenses recorded for this period."))}</small></div><div><b>${esc(t("Guardas","Save"))}: ${money(sav)}</b><small>${esc(t("Dinero apartado para tus metas.","Money set aside for your goals."))}</small></div></div><button class="btn" onclick="renderHago()">${esc(t("¿QUÉ HAGO CON ESTO?","WHAT DO I DO WITH THIS?"))}</button></div></section>`,t("Mi periodo","My period"))}
function getPurchase(){return getJSON("remesas_purchase_v4",[])}
function renderPurchase(){renderShell(`<section class="section"><div class="card"><h1>🛒 ${esc(t("PLANEAR UNA COMPRA","PLAN A PURCHASE"))}</h1><p>${esc(t("Antes de comprar, mira qué pasa con tu dinero después.","Before buying, see what happens to your money afterward."))}</p><label>${esc(t("¿Qué quieres comprar?","What do you want to buy?"))}</label><input id="purchaseName" maxlength="120"><label>${esc(t("¿Cuánto cuesta?","How much does it cost?"))}</label><input id="purchaseAmount" type="number" min=".01" step=".01"><button class="btn" onclick="checkPurchase()">${esc(t("VER QUÉ PASA","SEE WHAT HAPPENS"))}</button></div></section>`,t("Compra","Purchase"))}
function checkPurchase(){const n=(document.getElementById("purchaseName")?.value||"").trim(),a=num(document.getElementById("purchaseAmount")?.value),m=getMoneyState();if(!n||a<=0){showError(t("Dime qué quieres comprar y cuánto cuesta.","Tell me what you want to buy and how much it costs."));return}const after=num(m.available)-a,explain=after>=0?t(`Después de esa compra te quedarían ${money(after)} según tus registros. Eso te permite ver la consecuencia antes de gastar.`,`After that purchase, you would have ${money(after)} left according to your records. This lets you see the consequence before spending.`):t(`Esa compra supera en ${money(Math.abs(after))} lo que aparece libre. Si la haces, tendrás que usar dinero que ya tiene otro destino o cambiar algo de tu plan.`,`That purchase exceeds the amount shown as free by ${money(Math.abs(after))}. If you make it, you would need to use money already assigned elsewhere or change your plan.`);renderShell(`<section class="section"><div class="card"><h1>${esc(n)}</h1><div class="notice"><h2>${money(after)}</h2><p>${esc(explain)}</p></div><button class="btn" onclick="renderPuedo()">${esc(t("REVISAR MIS NÚMEROS","REVIEW MY NUMBERS"))}</button><button class="btn secondary" onclick="renderHome()">${esc(t("VOLVER","BACK"))}</button></div></section>`,t("Resultado","Result"))}
function showError(m){let old=document.querySelector(".toast");if(old)old.remove();const b=document.createElement("div");b.className="toast";b.textContent=m;document.body.appendChild(b);setTimeout(()=>b.remove(),6000)}
async function changeLanguage(){APP.lang=APP.lang==="es"?"en":"es";localStorage.setItem("remesas_lang_v4",APP.lang);await loadConfig();renderHome()}
function deleteLocalData(){if(!confirm(t("¿Quieres borrar tus datos guardados en este dispositivo? Se borrarán dinero, gastos, familia, ahorros y metas.","Do you want to delete your saved data on this device? Money, expenses, family, savings, and goals will be deleted.")))return;[APP.moneyKey,APP.expensesKey,APP.familyKey,APP.prefsKey,APP.savingsKey,APP.plansKey,"remesas_purchase_v4"].forEach(k=>localStorage.removeItem(k));location.reload()}
async function start(){try{await loadConfig();if(await verifyAccess()){if(!APP.session)await startService();renderHome()}else renderGate()}catch(e){renderGate()}}
Object.assign(window,{renderHome,renderAbout,renderRemittance,renderMoney,renderWeek,renderPeriod,renderExpenses,renderFamily,renderHelp,renderPurchase,renderSavings,renderGoals,renderTengo,renderGano,renderPuedo,renderHago,renderQuickGuide,renderLearn,showLesson,changeLanguage,understandNeed,compare,selectProvider,renderFinalCheck,finishCheck,renderComparisonFromSession,openOfficial,calculateMoney:renderMoney,addExpense,removeExpense,saveFamily,removeFamily,saveSavings,removeSavings,savePlan,removePlan,checkPurchase,showHelpTopic,deleteLocalData,pickPDF,restorePDF,exportMoneyPDF,exportLearningPDF,startPaidAccess,showServiceInfo,showAdmin,adminLogin,saveTengo,saveGano});
start();
